<div class="table-wrap"><table><tr><th>Business</th><th>Owner</th><th>Category</th><th>Location</th><th>Submitted</th><th>Actions</th></tr><?php foreach($pending as $b):?><tr><td><a href="index.php?page=business&id=<?=$b['id']?>"><?=e($b['name'])?></a></td><td><?=e($b['owner'])?></td><td><?=e($b['category'])?></td><td><?=e($b['barangay'])?>, <?=e($b['city'])?></td><td><?=e(date('M j, Y',strtotime($b['created_at'])))?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><button name="action" value="business_status" class="button coral" onclick="this.form.status.value='approved'">Approve</button><input type="hidden" name="status" value="approved"><button name="action" value="business_status" class="link-button" onclick="this.form.status.value='rejected'">Reject</button></form></td></tr><?php endforeach;if(!$pending):?><tr><td colspan="6">No businesses are waiting for verification.</td></tr><?php endif?></table></div>
